INSERT INTO MES_CX_SCHEDULE_RESULT ( ID, CX_BATCH_NO, ORDER_NO, SCHEDULE_DATE, MACHINE_CODE, MACHINE_NAME, LH_MACHINE_CODE, LH_MACHINE_NAME, AVAILABLE_MOLD_QTY, MATERIAL_CODE, MES_MATERIAL_CODE, SPEC_DESC, EMBRYO_CODE, EMBRYO_SPEC_DESC, CLASS1_PLAN_QTY_SEQ, CLASS1_ANALYSIS_INPUT, CLASS1_ANALYSIS, CLASS1_PLAN_QTY, CLASS1_EXAMPLE_TYPE, CLASS1_EXAMPLE_NO, CLASS2_PLAN_QTY_SEQ, CLASS2_ANALYSIS_INPUT, CLASS2_ANALYSIS, CLASS2_PLAN_QTY, CLASS2_EXAMPLE_TYPE, CLASS2_EXAMPLE_NO, CLASS3_PLAN_QTY_SEQ, CLASS3_ANALYSIS_INPUT, CLASS3_ANALYSIS, CLASS3_PLAN_QTY, CLASS3_EXAMPLE_TYPE, CLASS3_EXAMPLE_NO, DATA_VERSION, COMPANY_CODE, FACTORY_CODE ) SELECT * FROM (
SELECT #{item.id} AS ID, #{item.cxBatchNo} AS CX_BATCH_NO, #{item.orderNo} AS ORDER_NO, #{item.scheduleDate} AS SCHEDULE_DATE, #{item.machineCode} AS MACHINE_CODE, #{item.machineName} AS MACHINE_NAME, #{item.lhMachineCode} AS LH_MACHINE_CODE, #{item.lhMachineName} AS LH_MACHINE_NAME, #{item.availableMoldQty} AS AVAILABLE_MOLD_QTY, #{item.materialCode} AS MATERIAL_CODE, #{item.mesMaterialCode} AS MES_MATERIAL_CODE, #{item.specDesc} AS SPEC_DESC, #{item.embryoCode} AS EMBRYO_CODE, #{item.embryoSpecDesc} AS EMBRYO_SPEC_DESC, #{item.class1PlanQtySeq} AS CLASS1_PLAN_QTY_SEQ, #{item.class1AnalysisInput} AS CLASS1_ANALYSIS_INPUT, #{item.class1Analysis} AS CLASS1_ANALYSIS, #{item.class1PlanQty} AS CLASS1_PLAN_QTY, #{item.class1ExampleType} AS CLASS1_EXAMPLE_TYPE, #{item.class1ExampleNo} AS CLASS1_EXAMPLE_NO, #{item.class2PlanQtySeq} AS CLASS2_PLAN_QTY_SEQ, #{item.class2AnalysisInput} AS CLASS2_ANALYSIS_INPUT, #{item.class2Analysis} AS CLASS2_ANALYSIS, #{item.class2PlanQty} AS CLASS2_PLAN_QTY, #{item.class2ExampleType} AS CLASS2_EXAMPLE_TYPE, #{item.class2ExampleNo} AS CLASS2_EXAMPLE_NO, #{item.class3PlanQtySeq} AS CLASS3_PLAN_QTY_SEQ, #{item.class3AnalysisInput} AS CLASS3_ANALYSIS_INPUT, #{item.class3Analysis} AS CLASS3_ANALYSIS, #{item.class3PlanQty} AS CLASS3_PLAN_QTY, #{item.class3ExampleType} AS CLASS3_EXAMPLE_TYPE, #{item.class3ExampleNo} AS CLASS3_EXAMPLE_NO, #{item.dataVersion} AS DATA_VERSION, #{item.companyCode} AS COMPANY_CODE, #{item.factoryCode} AS FACTORY_CODE
) AS t WHERE NOT EXISTS ( SELECT 1 FROM MES_CX_SCHEDULE_RESULT WHERE CX_BATCH_NO = t.CX_BATCH_NO AND SCHEDULE_DATE = t.SCHEDULE_DATE AND DATA_VERSION = t.DATA_VERSION )

